    static bool showConsole = false;
    showConsole = !showConsole;
    ShowWindow(GetConsoleWindow(), showConsole ? SW_SHOW : SW_HIDE);
}

static executefn_t ExecuteFunc;
static HWND robloxWindow;
LRESULT CALLBACK NostalgiaWindowProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static HWND hTextBox;
    static HWND hExecuteButton;
    static HWND hClearButton;
    static HWND hConsoleButton;
    static HBRUSH hPinkBrush;

    switch (msg) {
    case WM_CREATE: {
        hTextBox = CreateWindowEx(
            WS_EX_CLIENTEDGE, "EDIT", "-- Enter script here",
            WS_CHILD | WS_VISIBLE | WS_BORDER | ES_MULTILINE | ES_AUTOVSCROLL | ES_AUTOHSCROLL | WS_VSCROLL | WS_HSCROLL,
            10, 10, 760, 540,
            hwnd, NULL, ((LPCREATESTRUCT)lParam)->hInstance, NULL
        );

        if (hTextBox == NULL) {
            MessageBox(hwnd, "Failed to create text box!", "Error", MB_ICONERROR);
            return -1;
        }

        hPinkBrush = CreateSolidBrush(RGB(61, 112, 255));
        if (hPinkBrush == NULL) {
            MessageBox(hwnd, "Failed to create pink brush!", "Error", MB_ICONERROR);
            return -1;
        }

        hExecuteButton = CreateWindow(
            "BUTTON", "EXECUTE",
            WS_TABSTOP | WS_VISIBLE | WS_CHILD | BS_DEFPUSHBUTTON,
            10, 560, 100, 30,
            hwnd, (HMENU)ID_EXECUTE, ((LPCREATESTRUCT)lParam)->hInstance, NULL
        );

        hClearButton = CreateWindow(
            "BUTTON", "CLEAR",
            WS_TABSTOP | WS_VISIBLE | WS_CHILD | BS_DEFPUSHBUTTON,
            120, 560, 100, 30,
            hwnd, (HMENU)ID_CLEAR, ((LPCREATESTRUCT)lParam)->hInstance, NULL
        );

        hConsoleButton = CreateWindow(
            "BUTTON", "CONSOLE",
            WS_TABSTOP | WS_VISIBLE | WS_CHILD | BS_DEFPUSHBUTTON,
            230, 560, 100, 30,
            hwnd, (HMENU)ID_CONSOLE, ((LPCREATESTRUCT)lParam)->hInstance, NULL
        );

        if (hExecuteButton == NULL || hClearButton == NULL || hConsoleButton == NULL) {
            MessageBox(hwnd, "Failed to create buttons!", "Error", MB_ICONERROR);
            return -1;
        }

        hAccelTable = CreateAcceleratorTable(accelTable, sizeof(accelTable) / sizeof(ACCEL));
        if (hAccelTable == NULL) {
            MessageBox(hwnd, "Failed to create accelerator table!", "Error", MB_ICONERROR);
            return -1;
        }

        SendMessageA(hTextBox, EM_SETLIMITTEXT, (WPARAM)1000000 * 100, 0); // 100 million chars

        return 0;
    }
    case WM_SYSCOMMAND: {
        if (wParam == SC_MINIMIZE) {
            // When minimized, focus on the Roblox window to prevent beeping
            if (robloxWindow) {
                SetForegroundWindow(robloxWindow);
            }
            return DefWindowProc(hwnd, msg, wParam, lParam);
        }
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }
    case WM_SIZE: {
        int width = LOWORD(lParam);
        int height = HIWORD(lParam);

        SetWindowPos(hTextBox, NULL, 10, 10, width - 20, height - 60, SWP_NOZORDER | SWP_NOACTIVATE);
        SetWindowPos(hExecuteButton, NULL, 10, height - 40, 100, 30, SWP_NOZORDER | SWP_NOACTIVATE);
        SetWindowPos(hClearButton, NULL, 120, height - 40, 100, 30, SWP_NOZORDER | SWP_NOACTIVATE);
        SetWindowPos(hConsoleButton, NULL, 230, height - 40, 100, 30, SWP_NOZORDER | SWP_NOACTIVATE);
        break;
    }
    case WM_GETMINMAXINFO: {
        MINMAXINFO* pMinMax = (MINMAXINFO*)lParam;
        pMinMax->ptMinTrackSize.x = 400;
        pMinMax->ptMinTrackSize.y = 300;
        break;
    }
    case WM_CTLCOLOREDIT: {
        HDC hdc = (HDC)wParam;
        HWND hEdit = (HWND)lParam;
        SetBkColor(hdc, RGB(61, 112, 255));
        SetTextColor(hdc, RGB(0, 0, 0));
        return (LRESULT)hPinkBrush;
    }
    case WM_PAINT: {
        PAINTSTRUCT ps;
        HDC hdc = BeginPaint(hwnd, &ps);
        HBRUSH hBrush = CreateSolidBrush(RGB(255, 0, 102));
        FillRect(hdc, &ps.rcPaint, hBrush);
        DeleteObject(hBrush);
        EndPaint(hwnd, &ps);
        break;
    }
    case WM_COMMAND: {
        switch (LOWORD(wParam)) {
        case ID_SELECTALL:
            SendMessage(hTextBox, EM_SETSEL, 0, -1);
            break;
        case ID_COPY:
            SendMessage(hTextBox, WM_COPY, 0, 0);
            break;
        case ID_PASTE:
            SendMessage(hTextBox, WM_PASTE, 0, 0);
            break;
        case ID_EXECUTE: {
            int length = GetWindowTextLength(hTextBox);
            if (length > 0) {
                char* textBuffer = new char[length + 1];
                GetWindowText(hTextBox, textBuffer, length + 1);
                ExecuteFunc(textBuffer);
                delete[] textBuffer;
            }
            break;
        }
        case ID_CLEAR:
            SetWindowText(hTextBox, "");
            break;
        case ID_CONSOLE:
            CallConsoleFunction();
            break;
        }
        break;
    }
    case WM_DESTROY: {
        if (hPinkBrush) {
            DeleteObject(hPinkBrush);
        }
        PostQuitMessage(0);
        return 0;
    }
    default:
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    return 0;
}

void SetupWindow(executefn_t executefn) {
    robloxWindow = FindWindowW(NULL, L"Roblox");
    ExecuteFunc = executefn;

    WNDCLASSA wndClass = { };
    wndClass.lpszClassName = "nostalgiaconvwnd";
    wndClass.lpfnWndProc = NostalgiaWindowProc;
    wndClass.hInstance = GetModuleHandle(NULL);
    wndClass.hCursor = LoadCursor(NULL, IDC_ARROW);

    ATOM classAtom = RegisterClassA(&wndClass);
    if (!classAtom) {
        MessageBox(NULL, "Failed to register class atom!", "Error", MB_ICONERROR);
        return;
    }

    HWND window = CreateWindowExA(
        WS_EX_APPWINDOW, "nostalgiaconvwnd", "NostalgiaConv",
        WS_OVERLAPPEDWINDOW | WS_VISIBLE,
        400, 400, 800, 600, robloxWindow, NULL, GetModuleHandle(NULL), NULL
    );

    if (window == NULL) {
        MessageBox(NULL, "Failed to create window!", "Error", MB_ICONERROR);
        return;
    }

    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        if (!TranslateAccelerator(window, hAccelTable, &msg)) {
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }
    }
}

BOOL WINAPI CtrlHandler(DWORD dwCtrlType) {
    return TRUE;
}

void MakeConsole(const std::string& title) {
    DWORD oldProt = 0;
    VirtualProtect(&FreeConsole, 1, PAGE_EXECUTE_READWRITE, &oldProt);
    *reinterpret_cast<std::uint8_t*>(&FreeConsole) = 0xC3;
    VirtualProtect(&FreeConsole, 1, oldProt, &oldProt);

    AllocConsole();
    freopen("CONOUT$", "w", stdout);
    freopen("CONIN$", "r", stdin);

    SetConsoleTitleA(title.c_str());

    SetConsoleCtrlHandler(&CtrlHandler, TRUE);
}

/*
Program     : Class definition for implementing Queue(Circular) using arrays.
Author      : © Vipin Kumar
Created on  : March 11, 2018 20:57 IST
*/

#include <iostream>
#include <cstdlib>
#include <conio.h>
#include <stdlib.h>
#define SIZE 10

using namespace std;

class Queue {
	/*
	Summary
	-------
	Create a class to implement Queue(circular) using dynamically created array.

	Extended Summary
	----------------
	This is a class definition of a Queue(Circular) which is created using a
	dynamically created array. By dynamically created array, we means that the
	array will be created when it is to be used and deleted afterwards.
	The queue will be circular in nature i.e, the `head` index will be at index
	`rear`+1.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	Class definition

	Class Variables
	---------------
	queueArray	: Dynamic array, to store the queue elements.
	capacity	: Maximum capacity of the queue.
	front		: `front` points to the front element in the queue.
	rear		: `rear` points to last element in the queue.
	count		: Current size of the queue.

	Member Functions
	----------------
	Queue()		: Constructor of class Queue.
	~Queue()	: Destructor the class Queue.
	dequeue()	: void - deleting the element.
	enqueue()	: void - inserting the element.
	peek()		: int - returns front element.
	size()		: int - returns current size of the queue.
	isEmpty()	: bool - check if queue is empty.
	isFull()	: bool - check if queue is full.
	display()	: void - display the contents of queue.

	Approach
	--------
	Class definition provides data member and member functions for the 
	Queue class.
	*/

public:
	int *queueArray;							
	int capacity;								
	int front;									
	int rear;									
	int count;									

	Queue();									
	~Queue();									
	void dequeue();								
	void enqueue(int);							
	int peek();  								
	int size();									
	bool isEmpty();								
	bool isFull();								
	void display();								
};

Queue::Queue() {
	/*
	Summary
	-------
	Create a constructor for Queue class.

	Extended Summary
	----------------
	This is a constructor definition of a Queue class. This constructor
	initializes the class variables and alloted memory space for the
	them. It also creates the dynamic array. A Constructor definition
	is necessary because of it's importance in memory allotment.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	Queue Constructor definition.

	Approach
	--------
	Constructor definition provides information of data member when they 
	are being initialized at run time.
	*/

	capacity = 0;
	count = 0;
	front = -1;
	rear = -1;
	queueArray = new int[SIZE];
}

Queue::~Queue() {
	/*
	Summary
	-------
	Create a destructor for Queue class.

	Extended Summary
	----------------
	This is a destructor definition of a Queue class. This destructor
	deletes the dynamically alloted variables and free the space.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	Queue Destructor definition.

	Approach
	--------
	Destructor definition provides information of data member when they are
	being deleted at run time.
	*/

	delete queueArray;
}

bool Queue::isEmpty () {
	/*
	Summary
	-------
	Create isEmpty() function.

	Extended Summary
	----------------
	isEmpty function tells about the condition when the queue is empty. This condition 
	will be checked while deleting elements from the queue as we can't delete any 
	element from empty queue.

	Parameters
	----------
	None

	Returns
	-------
	true - bool value, if queue is empty.
	false - bool value, if queue is not empty.

	Description
	-----------
	isEmpty() function definition.

	Approach
	--------
	Check the value of `front` if it is -1.
	*/

	if (front == -1) {
		return true;
	}
	else {
		return false;
	}
}

bool Queue::isFull () {
	/*
	Summary
	-------
	Create isFull() function.

	Extended Summary
	----------------
	isFull function tells about the condition when the queue is full. This condition 
	will be checked while inserting elements in the queue as we can't insert any 
	element in a queue which is full.

	Parameters
	----------
	None

	Returns
	-------
	true - bool value, if queue is full.
	false - bool value, if queue is not full.

	Description
	-----------
	isFull() function definition.

	Approach
	--------
	Check the value of `rear` if it is SIZE - 1.
	*/

	if ((rear == capacity - 1 && front == 0) || (rear == front - 1)) {
		return true;
	}
	else {
		return false;
	}
}

void Queue::enqueue (int element) {
	/*
	Summary
	-------
	Create enqueue() function.

	Extended Summary
	----------------
	enqueue() function will insert the element specified by the argument. The 
	element will be added at the `rear` end of the queue. The element can be inserted 
	only when queue is not full. In case, it will prompt that queue is already full.
	With the insertion of the element at `rear` end, it will also increment the current 
	size of the queue specified by the `count` variable.


	Parameters
	----------
	element : int - the element to be inserted at the rear end of the queue.

	Returns
	-------
	None

	Description
	-----------
	enqueue() function definition.

	Approach
	--------
	The element will be added at the `rear` end of the queue. When the `rear` will be
	`capacity`-1 and front is not zero, rear is set to zero and element is inserted at 
	rear end.
	*/

	if (isFull()) {
		cerr << "ERROR: Queue is already full. Delete some elements to enter more.";
		getch ();
		return;
	}

	// First element.
	else if (front == -1) {
		front = 0;
		rear = 0;
		queueArray[rear] = element;
		count++;
	}

	else if (rear == capacity - 1 && front != 0) {
			rear = 0;
			queueArray[rear] = element;
			count++;

	}

	else {
		rear++;
		queueArray[rear] = element;
		count++;
	}
}

void Queue::dequeue() {
	/*
	Summary
	-------
	Create dequeue() function.

	Extended Summary
	----------------
	dequeue() function will delete the element. The element at the `front` will be 
	deleted from the queue. The element can be deleted only when queue is not empty. 
	In case, it will prompt that queue is empty. With the deletion of the element from 
	`front`, it will also decrement the current size of the queue specified by the 
	`count` variable.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	dequeue() function definition.

	Approach
	--------
	The element will be deleted from the `front` size of the queue when queue is not empty. 
	When the `front` will be equal to `rear`, front will be set to -1, case of single element.
	In rest cases, front will be incremented, in case of front =  capacity - 1, front will be 
	incremented and due to circular nature of queue, it will be 0.
	*/

	if (isEmpty()) {
		cerr << "ERROR: Queue is empty. Insert some elements to delete.\n";
		getch ();
		return;
	}

	// In case of single element.
	else if (front == rear) {
		front = -1;
		rear = -1;
		count--;
	} 

	else if (front == capacity - 1) {
		front = 0;
		count--;
	}

	else {
		front++;
		count--;
	}
}

int Queue::peek () {
	/*
	Summary
	-------
	Create peek() function.

	Extended Summary
	----------------
	peek() function will gives the element present at front of queue, until the queue
	is not empty.In case of queue being empty, it will prompt that queue is empty
	and thus, no front element is there.

	Parameters
	----------
	None

	Returns
	-------
	queueArray[front] : int - front element of the queue.

	Description
	-----------
	peek() function definition.

	Approach
	--------
	Return queueArray[front] whenever queue is not empty.
	*/

	if (!isEmpty()) {
		return queueArray[front];
	}
	else {
		cout << "Queue is empty. No front element.\n";
		return -1;
	}

}

int Queue::size () {
	/*
	Summary
	-------
	Create size() function.

	Extended Summary
	----------------
	size() function will gives the current size of the queue. The current size will
	always be less than or equal to `capacity` of the queue.

	Parameters
	----------
	None

	Returns
	-------
	count : int - current size of the queue.

	Description
	-----------
	size() function definition.

	Approach
	--------
	Return value of `count` variable.
	*/

	return count;
}

void Queue::display () {
	/*
	Summary
	-------
	Create display() function.

	Extended Summary
	----------------
	display() function will display the content of queue i.e, the status of queue. Since, it
	is circular queue, some checks are required in order to get the exact status of the queue.
	When `rear` is ahead of `front`, we simply print queue from `front` to `rear`. In case when
	`front` is ahead of `rear`, we will be needed to print the queue in two parts - from `front`
	to `count` and from 0 to `rear`.

	Parameters
	----------
	None

	Returns
	-------
	None

	Description
	-----------
	display() function definition.

	Approach
	--------
	cout the content of array specified by queueArray varuable.
	*/

	if (isEmpty()) {
		cout << "Queue is Empty.";
		return;
	}

	cout << "Queue is ";
	if (rear >= front) {
		for (int i = front;  i <= rear;  i++) {
			cout << queueArray[i] << " ";
		}
	}

	else {
		for (int i = front; i < count; i++) {
			cout << queueArray[i] << " ";
		}

		for (int i = 0; i <= rear; i++) {
			cout << queueArray[i] << " ";
		}
	}
}

int main () {
	/*
	Summary
	-------
	Create main() function.

	Extended Summary
	----------------
	main() function will invoke all the member function defined under class Queue 
	according to their need and usability with the help of object of class.

	Parameters
	----------
	None

	Returns
	-------
	0 : int - succesful termination of program.

	Description
	-----------
	main() function definition.

	Approach
	--------
	Switch cases are used to different functionalities under class Queue.
	*/

	// Object of class Queue.
	Queue q;

	int choice;
	int element;
	int peekElement;
	int currentSize;

	system ("cls");
	cout << "\t\t***** CIRCULAR QUEUE USING ARRAY\n\n";
	cout << "Enter the capacity of queue: ";
	cin >> q.capacity;

	q.queueArray = new int[q.capacity];

	// Menu driven.
	while (true) {
		system("cls");
		cout << "\t\t***** CIRCULAR QUEUE USING ARRAY\n\n";
		cout << "1. ENQUEUE\n";
		cout << "2. DEQUEUE\n";
		cout << "3. FRONT ELEMENT\n";
		cout << "4. SIZE\n";
		cout << "5. DISPLAY\n";
		cout << "6. EXIT\n";

		cout << "Enter the choice: ";
		cin >> choice;

		switch (choice) {

		// Enqueue an `element`.
		case 1: cout << "Enter the element: ";
				cin >> element;
				q.enqueue (element);
				q.display ();
				getch ();
				break;

		// Dequeue from the front of queue.
		case 2: q.dequeue ();
				q.display ();
				getch ();
				break;

		// Front element of queue. 
		case 3: peekElement = q.peek ();
				if (!q.isEmpty()) {
					cout << "Front element is " << peekElement;
				}
				getch ();
				break;

		// Current size of queue.
		case 4: currentSize = q.size ();
				cout << "Current size of queue is " << currentSize;
				getch ();
				break;

		// Display content of queue i.e, current status.
		case 5: q.display ();
				getch ();
				break;

		// Exit from the program.
		case 6: exit (0);
				break;

		// Wrong Choice entered.
		default:
			cerr << "ERROR: Invalid Choice, re-enter your choice.\n";
			getch ();
			break;
		}
	}
	getch();
	return 0;
}

#include <iostream>

void foo(int*& ptr) // pass pointer by reference
{
    ptr = nullptr; // 실제 ptr 인수를 변경할 수 있다.
    //NULL 포인터로 초기화된 포인터는 메모리상 어떠한 값도 가리키지 않음
    //그러나 초기화되지 않은 포인터는 어떤 값이라도 포함될 수 있고, 참조될 수 있다.
}

int main()
{
    int x = 5;
    int *ptr = &x;
    std::cout << "ptr is: " << (ptr ? "non-null" : "null") << '\n'; // prints non-null
    foo(ptr);
    std::cout << "ptr is: " << (ptr ? "non-null" : "null") << '\n'; // prints null

    return 0;
}

// ########Supported via standard programming aids4o ################
/*
포인터를 참조로 전달하는 방식(`int*&`)은 C++에서 강력한 기능으로, 여러 상황에서 유용합니다. 
이 방식은 주로 함수가 인자로 전달된 포인터를 수정해야 하는 경우에 사용됩니다. 이제 이 방법이 필요한 경우와 그 장점에 대해 설명하겠습니다.

### 1. 포인터를 참조로 전달해야 하는 상황

#### **1.1 동적 메모리 할당**
동적 메모리 할당을 처리하는 함수에서 사용됩니다. 함수가 포인터를 수정하여 호출자에게 새로운 메모리를 할당해주어야 할 때 포인터를 참조로 전달합니다.

예를 들어, 동적 배열을 초기화하는 함수를 작성할 때:
*/

void allocateArray(int*& ptr, int size)
{
    ptr = new int[size]; // 메모리 할당
}

int main()
{
    int* array = nullptr;
    allocateArray(array, 10); // array 포인터가 새 메모리를 가리키도록 수정됨

    // 할당된 배열 사용
    for (int i = 0; i < 10; ++i)
    {
        array[i] = i;
    }

    delete[] array; // 동적 메모리 해제
    return 0;
}

/*
이 예제에서 `allocateArray` 함수는 포인터를 수정하여 `main` 함수에서 사용할 동적 배열을 할당합니다.
포인터를 참조로 전달함으로써, 함수 내에서 메모리 할당을 수행하고 그 결과를 호출자에게 반환할 수 있습니다.

#### **1.2 리소스 해제 및 초기화**
포인터가 동적 자원(예: 메모리, 파일 핸들)을 관리할 때, 함수가 그 포인터를 초기화하거나 자원을 해제한 후 포인터를 무효화해야 할 때 사용됩니다. 

예를 들어, 동적 메모리를 해제하고 포인터를 `nullptr`로 초기화하는 경우:

*/
void deleteArray(int*& ptr)
{
    delete[] ptr; // 동적 메모리 해제
    ptr = nullptr; // 포인터를 무효화
}

int main()
{
    int* array = new int[10];
    deleteArray(array); // 메모리 해제 및 포인터 무효화

    if (array == nullptr) {
        std::cout << "Array pointer is null\n";
    }

    return 0;
}
/*

이 예제에서, `deleteArray` 함수는 포인터를 초기화하고, 메모리를 안전하게 관리할 수 있도록 합니다. 이렇게 하면 해제된 메모리를 가리키는 포인터를 다시 사용하는 실수를 방지할 수 있습니다.

### 2. 포인터를 참조로 전달하는 장점

#### **2.1 포인터의 수정이 가능**
포인터를 참조로 전달하면 함수 내에서 인자로 전달된 포인터를 직접 수정할 수 있습니다. 이는 포인터가 가리키는 메모리 주소를 변경하거나, 
자원을 해제한 후 포인터를 `nullptr`로 설정하는 등의 작업을 가능하게 합니다.

- **함수 내에서 포인터 변경**: 포인터를 참조로 전달하면 함수 내에서 포인터가 가리키는 주소 자체를 변경할 수 있습니다. 이를 통해 함수가 포인터가 가리키는 대상을 변경할 수 있습니다.

#### **2.2 불필요한 복사를 피할 수 있음**
포인터를 참조로 전달하면 포인터의 복사가 발생하지 않으므로, 함수 호출 시 성능에 더 유리할 수 있습니다. 특히 큰 구조체나 객체를 포인터로 가리키는 경우, 
포인터의 복사는 의미가 없고 불필요합니다. 참조로 전달하면 이 복사 비용을 피할 수 있습니다.

#### **2.3 명확한 의도 표현**
코드의 의도가 명확해집니다. 포인터를 참조로 전달함으로써, 함수가 인자로 받은 포인터를 수정할 것임을 명확히 나타낼 수 있습니다. 이는 함수의 인터페이스를 이해하는 데 도움이 됩니다.

### 3. 결론

포인터를 참조로 전달하는 방식은 다음과 같은 경우에 유용합니다:

- 함수가 포인터를 수정해야 할 때.
- 동적 메모리 할당 및 해제를 처리할 때.
- 포인터의 주소를 변경하거나 초기화할 필요가 있을 때.

이 방식은 코드의 효율성을 높이고, 메모리 관리와 같은 중요한 작업에서 실수를 줄여주는 역할을 합니다. 이를 통해 더 안전하고 효율적인 C++ 코드를 작성할 수 있습니다.
*/

#include <bits/stdc++.h>
