{
    int n;
    cin >> n;
    vector<int>v(7);
    for (int i = 0; i < 7; i++)
    {
        cin >> v[i];
    }
    int i = 0;
    int total = 0;
    while (total < n)
    {
        total += v[i];
        if (total >= n)
        {
            cout << i+1;
        }
        i++;
        if (i >= 7)
        i = 0;
    }
}


