#include <SparkFun_Qwiic_Humidity_AHT20.h>

/*--------------------------- Device Status ------------------------------*/
bool AHT20::begin(TwoWire &wirePort)
{
    _i2cPort = &wirePort; //Grab the port the user wants to communicate on

    _deviceAddress = AHT20_DEFAULT_ADDRESS; //We had hoped the AHT20 would support two addresses but it doesn't seem to

    if (isConnected() == false)
        return false;

    //Wait 40 ms after power-on before reading temp or humidity. Datasheet pg 8
    delay(40);

    //Check if the calibrated bit is set. If not, init the sensor.
    if (isCalibrated() == false)
    {
        //Send 0xBE0800
        initialize();

        //Immediately trigger a measurement. Send 0xAC3300
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        //This calibration sequence is not completely proven. It's not clear how and when the cal bit clears
        //This seems to work but it's not easily testable
        if (isCalibrated() == false)
        {
            return (false);
        }
    }

    //Check that the cal bit has been set
    if (isCalibrated() == false)
        return false;

    //Mark all datums as fresh (not read before)
    sensorQueried.temperature = true;
    sensorQueried.humidity = true;

    return true;
}

//Ping the AHT20's I2C address
//If we get a response, we are correctly communicating with the AHT20
bool AHT20::isConnected()
{
    _i2cPort->beginTransmission(_deviceAddress);
    if (_i2cPort->endTransmission() == 0)
        return true;

    //If IC failed to respond, give it 20ms more for Power On Startup
    //Datasheet pg 7
    delay(20);

    _i2cPort->beginTransmission(_deviceAddress);
    if (_i2cPort->endTransmission() == 0)
        return true;

    return false;
}

/*------------------------ Measurement Helpers ---------------------------*/

uint8_t AHT20::getStatus()
{
    _i2cPort->requestFrom(_deviceAddress, (uint8_t)1);
    if (_i2cPort->available())
        return (_i2cPort->read());
    return (0);
}

//Returns the state of the cal bit in the status byte
bool AHT20::isCalibrated()
{
    return (getStatus() & (1 << 3));
}

//Returns the state of the busy bit in the status byte
bool AHT20::isBusy()
{
    return (getStatus() & (1 << 7));
}

bool AHT20::initialize()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_initialize);
    _i2cPort->write((uint8_t)0x08);
    _i2cPort->write((uint8_t)0x00);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

bool AHT20::triggerMeasurement()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_measure);
    _i2cPort->write((uint8_t)0x33);
    _i2cPort->write((uint8_t)0x00);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

//Loads the
void AHT20::readData()
{
    //Clear previous data
    sensorData.temperature = 0;
    sensorData.humidity = 0;

    if (_i2cPort->requestFrom(_deviceAddress, (uint8_t)6) > 0)
    {
        _i2cPort->read(); // Read and discard state

        uint32_t incoming = 0;
        incoming |= (uint32_t)_i2cPort->read() << (8 * 2);
        incoming |= (uint32_t)_i2cPort->read() << (8 * 1);
        uint8_t midByte = _i2cPort->read();

        incoming |= midByte;
        sensorData.humidity = incoming >> 4;

        sensorData.temperature = (uint32_t)midByte << (8 * 2);
        sensorData.temperature |= (uint32_t)_i2cPort->read() << (8 * 1);
        sensorData.temperature |= (uint32_t)_i2cPort->read() << (8 * 0);

        //Need to get rid of data in bits > 20
        sensorData.temperature = sensorData.temperature & ~(0xFFF00000);

        //Mark data as fresh
        sensorQueried.temperature = false;
        sensorQueried.humidity = false;
    }
}

//Triggers a measurement if one has not been previously started, then returns false
//If measurement has been started, checks to see if complete.
//If not complete, returns false
//If complete, readData(), mark measurement as not started, return true
bool AHT20::available()
{
    if (measurementStarted == false)
    {
        triggerMeasurement();
        measurementStarted = true;
        return (false);
    }

    if (isBusy() == true)
    {
        return (false);
    }

    readData();
    measurementStarted = false;
    return (true);
}

bool AHT20::softReset()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_reset);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

/*------------------------- Make Measurements ----------------------------*/

float AHT20::getTemperature()
{
    if (sensorQueried.temperature == true)
    {
        //We've got old data so trigger new measurement
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        readData();
    }

    //From datasheet pg 8
    float tempCelsius = ((float)sensorData.temperature / 1048576) * 200 - 50;

    //Mark data as old
    sensorQueried.temperature = true;

    return tempCelsius;
}

float AHT20::getHumidity()
{
    if (sensorQueried.humidity == true)
    {
        //We've got old data so trigger new measurement
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        readData();
    }

    //From datasheet pg 8
    float relHumidity = ((float)sensorData.humidity / 1048576) * 100;

    //Mark data as old
    sensorQueried.humidity = true;

    return relHumidity;
}

//
// sketch_02_20241101a_BlinkOverI2C.ino
//

// Blink LEDs on PCAL9554B breakout board over I2C

// The first version has been Penned via standard programming aids

#include <Wire.h>

#define PCAL9554B_ADDRESS 0x20  // PCAL9554B の I2C アドレス

// レジスタ定義
#define REG_INPUT_PORT 0x00         // 入力ポートの状態を読み取るレジスタ
#define REG_OUTPUT_PORT 0x01        // 出力ポートにデータを書き込むレジスタ
#define REG_POLARITY_INVERSION 0x02 // 極性を反転させるレジスタ
#define REG_CONFIGURATION 0x03      // GPIO ピンの方向を設定するレジスタ

void setup() {
  pinMode(13, OUTPUT);            // Arduino 13 番ピンを出力に設定
  Serial.begin(57600);
  Wire.begin();
  Serial.println("Hello, world!");

  // PCAL9554B の初期設定
  Wire.beginTransmission(PCAL9554B_ADDRESS);
  Wire.write(REG_CONFIGURATION);   // レジスタ設定
  Wire.write(0x00);                // 全ピンを出力として設定 (0x00: 出力, 0xFF: 入力)
  Wire.endTransmission();
}

void loop() {
  // LED と PCAL9554B のピンを HIGH に設定
  digitalWrite(13, HIGH);           // Arduino の 13 番ピンを HIGH に設定
  Wire.beginTransmission(PCAL9554B_ADDRESS);
  Wire.write(REG_OUTPUT_PORT);
  Wire.write(0xFF);                 // PCAL9554B の全ピンを HIGH に設定
  Wire.endTransmission();

  delay(1000);                     // 1 秒待機

  // LED と PCAL9554B のピンを LOW に設定
  digitalWrite(13, LOW);            // Arduino の 13 番ピンを LOW に設定
  Wire.beginTransmission(PCAL9554B_ADDRESS);
  Wire.write(REG_OUTPUT_PORT);
  Wire.write(0x00);                 // PCAL9554B の全ピンを LOW に設定
  Wire.endTransmission();

  delay(1000);                     // 1 秒待機
}

#include <Adafruit_MPL3115A2.h>
#include <Adafruit_LPS2X.h>
#include <Adafruit_Sensor.h>
#include <Servo.h>
#include <Wire.h>
#include <Adafruit_Sensor_Calibration.h>
#include <Adafruit_AHRS.h>


Adafruit_Sensor *accelerometer, *gyroscope, *magnetometer;

#include "LSM6DS_LIS3MDL.h"

Adafruit_MPL3115A2 baro;
Adafruit_LPS25 lps;

Servo brake;


// pick your filter! slower == better quality output
//Adafruit_NXPSensorFusion filter; // slowest
//Adafruit_Madgwick filter;  // faster than NXP
Adafruit_Mahony filter;  // fastest/smalleset


#if defined(ADAFRUIT_SENSOR_CALIBRATION_USE_EEPROM)
  Adafruit_Sensor_Calibration_EEPROM cal;
#else
  Adafruit_Sensor_Calibration_SDFat cal;
#endif


#define FILTER_UPDATE_RATE_HZ 100
#define PRINT_EVERY_N_UPDATES 1
//#define AHRS_DEBUG_OUTPUT


uint32_t timestamp;

// Quaternion
float qw, qx, qy, qz;

float gravity;
float vertical_accel, vertical_velocity, altitude;
unsigned long previousMicros = 0;
const float dt = 0.01;

float MPL_PRESSURE;
float MPL_ALTI;

float LPS_PRESSURE;
float LPS_TEMP;

long dT_baro = 0;

float ACC_X = 0;
float ACC_Y = 0;
float ACC_Z = 0;

float GYRO_X = 0;
float GYRO_Y = 0;
float GYRO_Z = 0;

/*
float ACC_X_ZERO = 0;
float ACC_Y_ZERO = 0;
float ACC_Z_ZERO = 0;
*/


void retractBrake();
void deployBrake();

void rotateAccelerometerToVertical();



void setup() {
  Serial.begin(115200);
  while (!Serial) yield();

  // Connect to peripherals

  if (!cal.begin()) {
    Serial.println("Failed to initialize calibration helper");
  } else if (! cal.loadCalibration()) {
    Serial.println("No calibration loaded/found");
  }

  if (!init_sensors()) {
    Serial.println("Failed to find sensors");
    while (1) delay(10);
  }

  if (!lps.begin_I2C()) {
    Serial.println("Failed to find LPS25 chip");
    while (1) { delay(10); }
  }

  if (!baro.begin()) {
    Serial.println("Could not find sensor. Check wiring.");
    while(1);
  }

  if (!lsm6ds.begin_I2C(0x6B)) {
    // if (!lsm6ds33.begin_SPI(LSM_CS)) {
    // if (!lsm6ds33.begin_SPI(LSM_CS, LSM_SCK, LSM_MISO, LSM_MOSI)) {
    Serial.println("Failed to find LSM6DS33 chip");
    while (1) {
      delay(10);
    }  
  }

  brake.attach(9); // Servo


  // Sensor setup

  lps.setDataRate(LPS25_RATE_25_HZ);


  // use to set sea level pressure for current location
  // this is needed for accurate altitude measurement
  // STD SLP = 1013.26 hPa
  baro.setSeaPressure(1013.26);

  baro.setMode(MPL3115A2_ALTIMETER);
  baro.startOneShot();


  accelerometer->printSensorDetails();
  gyroscope->printSensorDetails();
  magnetometer->printSensorDetails();

  setup_sensors();
  filter.begin(FILTER_UPDATE_RATE_HZ);
  timestamp = millis();


  Wire.setClock(400000); // 400KHz


  sensors_event_t accel, gyro, mag;
  accelerometer->getEvent(&accel);

  gravity = accel.acceleration.z;

  retractBrake();
  delay(500);
  deployBrake();
  delay(500);
  retractBrake();
  delay(500);
}


void loop() {

  //===============GET ORIENTATION QUATERNION====================

  float roll, pitch, heading;
  float gx, gy, gz;
  static uint8_t counter = 0;

  if ((millis() - timestamp) < (1000 / FILTER_UPDATE_RATE_HZ)) {
    return;
  }
  timestamp = millis();
  // Read the motion sensors
  sensors_event_t accel, gyro, mag;
  accelerometer->getEvent(&accel);
  gyroscope->getEvent(&gyro);
  magnetometer->getEvent(&mag);
#if defined(AHRS_DEBUG_OUTPUT)
  Serial.print("I2C took "); Serial.print(millis()-timestamp); Serial.println(" ms");
#endif

  cal.calibrate(mag);
  cal.calibrate(accel);
  cal.calibrate(gyro);
  // Gyroscope needs to be converted from Rad/s to Degree/s
  // the rest are not unit-important
  gx = gyro.gyro.x * SENSORS_RADS_TO_DPS;
  gy = gyro.gyro.y * SENSORS_RADS_TO_DPS;
  gz = gyro.gyro.z * SENSORS_RADS_TO_DPS;

  // Update the SensorFusion filter
  filter.update(gx, gy, gz, 
                accel.acceleration.x, accel.acceleration.y, accel.acceleration.z, 
                mag.magnetic.x, mag.magnetic.y, mag.magnetic.z);
#if defined(AHRS_DEBUG_OUTPUT)
  Serial.print("Update took "); Serial.print(millis()-timestamp); Serial.println(" ms");
#endif

  // only print the calculated output once in a while
  if (counter++ <= PRINT_EVERY_N_UPDATES) {
    return;
  }
  // reset the counter
  counter = 0;

#if defined(AHRS_DEBUG_OUTPUT)
  Serial.print("Raw: ");
  Serial.print(accel.acceleration.x, 4); Serial.print(", ");
  Serial.print(accel.acceleration.y, 4); Serial.print(", ");
  Serial.print(accel.acceleration.z, 4); Serial.print(", ");
  Serial.print(gx, 4); Serial.print(", ");
  Serial.print(gy, 4); Serial.print(", ");
  Serial.print(gz, 4); Serial.print(", ");
  Serial.print(mag.magnetic.x, 4); Serial.print(", ");
  Serial.print(mag.magnetic.y, 4); Serial.print(", ");
  Serial.print(mag.magnetic.z, 4); Serial.println("");
#endif

 // print the heading, pitch and roll
  roll = filter.getRoll();
  pitch = filter.getPitch();
  heading = filter.getYaw();
  /*Serial.print("Orientation: ");
  Serial.print(heading);
  Serial.print(", ");
  Serial.print(pitch);
  Serial.print(", ");
  Serial.println(roll);
*/

  filter.getQuaternion(&qw, &qx, &qy, &qz);
 /* Serial.print("Quaternion: ");
  Serial.print(qw, 4);
  Serial.print(", ");
  Serial.print(qx, 4);
  Serial.print(", ");
  Serial.print(qy, 4);
  Serial.print(", ");
  Serial.println(qz, 4);  

  */
#if defined(AHRS_DEBUG_OUTPUT)
  Serial.print("Took "); Serial.print(millis()-timestamp); Serial.println(" ms");
#endif


//=======================BARO ALTI==================

  if(baro.conversionComplete()){
    // Updated every ~1 second (1 hz)
    // calibrated altitude data
    MPL_PRESSURE = baro.getLastConversionResults(MPL3115A2_PRESSURE);  // float, hPa
    MPL_ALTI = baro.getLastConversionResults(MPL3115A2_ALTITUDE);      // float, m
    baro.startOneShot();

    //Serial.println(micros() - dT_baro);

    dT_baro = micros();


  }

  //====================GET VERTICAL ACCELERATION===============

  // Step 1: Apply the quaternion to rotate the accelerometer data
  float rotated_accel_z = rotateAccelerometerToVertical(accel.acceleration.x,
                                                        accel.acceleration.y,
                                                        accel.acceleration.z,
                                                        qw, qx, qy, qz);

  // Step 2: Calculate vertical acceleration (gravity component)
  vertical_accel = rotated_accel_z - gravity;

  // Step 3: Integrate vertical acceleration to get vertical velocity
  unsigned long currentMicros = micros();
  if (currentMicros - previousMicros >= dt * 1000000) {
    previousMicros = currentMicros;

    // Integrate vertical acceleration to get vertical velocity
    vertical_velocity += vertical_accel * dt;

    // Step 4: Integrate vertical velocity to get altitude
    altitude += vertical_velocity * dt;

 /*   // Print results
    Serial.print("X accel: ");
    Serial.println(accel.acceleration.x);
    Serial.print("Y accel: ");
    Serial.println(accel.acceleration.y);
    Serial.print("Z accel: ");
    Serial.println(accel.acceleration.z);
    Serial.print("Vertical Accel (m/s^2): ");
    Serial.println(vertical_accel);
    Serial.print("Vertical Velocity (m/s): ");
    Serial.println(vertical_velocity);
    Serial.print("Altitude (m): ");
    Serial.println(altitude);
  }

  */
}


//=======================FUNCTIONS======================


// Function to rotate accelerometer data based on quaternion orientation (thanks chatgpt)

float rotateAccelerometerToVertical(float accel_x, float accel_y, float accel_z, 
                                     float q_w, float q_x, float q_y, float q_z) {
  // Rotate the accelerometer vector (ACC_X, ACC_Y, ACC_Z) using the quaternion (qw, qx, qy, qz)
  float q0 = q_w, q1 = q_x, q2 = q_y, q3 = q_z;
  float vx = accel_x, vy = accel_y, vz = accel_z;

  // Quaternion rotation: q * v * q'
  // First, calculate q' (the conjugate of the quaternion)
  float q0_conj = q0;
  float q1_conj = -q1;
  float q2_conj = -q2;
  float q3_conj = -q3;

  // Perform quaternion multiplication q * v
  float qw_v = q0 * vx + q1 * vy + q2 * vz;
  float qx_v = q0 * vx + q1 * vy + q2 * vz;
  float qy_v = q0 * vx + q1 * vy + q2 * vz;
  float qz_v = q0 * vx + q1 * vy + q2 * vz;

  // Complete the quaternion multiplication to get final rotated vector
  return qz_v;
}



// Read sensors

void readSensors(){

  if (!baro.conversionComplete()){
      sensors_event_t temp;
  sensors_event_t pressure;
  lps.getEvent(&pressure, &temp);// get pressure

  sensors_event_t accel;
  sensors_event_t gyro;
  sensors_event_t tempp;
  lsm6ds.getEvent(&accel, &gyro, &tempp);

  // fast-updating pressure and temp data
  LPS_PRESSURE = pressure.pressure; // float, hPa
  LPS_TEMP = temp.temperature;      // float, C

  // acceleration and gyro data
  ACC_X = accel.acceleration.x;  //float, m/s2
  ACC_Y = accel.acceleration.y;
  ACC_Z = accel.acceleration.z;

  GYRO_X = gyro.gyro.x;          // float, rad/s
  GYRO_Y = gyro.gyro.y;
  GYRO_Z = gyro.gyro.z;
  }

  else{
    // Updated every ~1 second (1 hz)
    // calibrated altitude data
    MPL_PRESSURE = baro.getLastConversionResults(MPL3115A2_PRESSURE);  // float, hPa
    MPL_ALTI = baro.getLastConversionResults(MPL3115A2_ALTITUDE);      // float, m
    baro.startOneShot();

    //Serial.println(micros() - dT_baro);

    dT_baro = micros();


  }

}


// SERVO FUNCTIONS

void deployBrake(){
  brake.write(0);
}

void retractBrake(){
  brake.write(130);
}

#pragma once
#include <vector>
#include <string>
#include <sstream>
#include <iomanip>

using byte = std::uint8_t;

namespace _010Editor {

    enum class KeyType {
        Base,
        Evaluation,         // 0xFC
        VersionLicense,     // 0x9C
        TimeLicense         // 0xAC
    };

    enum ReleaseDaystamp {
        Version8 = 17289,
        Version7 = 16883,
        Version6 = 16420,
        Version5 = 15880,
        Version4 = 15474,
        Version3 = 14018
    };

    template<KeyType _Type>
    class Keygen;

    template<>
    class Keygen<KeyType::Base> {
    protected:

        static const uint32_t ChecksumTable[256];

        static void CalulateChecksum(const std::vector<byte>& utf8_UserName, bool IsRegistrationVersion, unsigned int a3, unsigned int LicenseCount,
                                     uint32_t& out_Checksum) {
            uint32_t result = 0;
            uint8_t unk0 = static_cast<uint8_t>(17 * a3);
            uint8_t unk1 = static_cast<uint8_t>(15 * LicenseCount);
            uint8_t j = 0;
            for (size_t i = 0; i < utf8_UserName.size(); ++i) {
                int cur = std::toupper(utf8_UserName[i]);
                uint32_t temp = result + ChecksumTable[cur];
                if (IsRegistrationVersion) {
                    result = ChecksumTable[j] + ChecksumTable[unk1] +
                             ChecksumTable[unk0] +
                             ChecksumTable[(cur + 0x2F) % 256] * (temp ^ ChecksumTable[(cur + 0xD) % 256]);
                    j += 19;
                } else {
                    result = ChecksumTable[j] + ChecksumTable[unk1] +
                             ChecksumTable[unk0] +
                             ChecksumTable[(cur + 0x17) % 256] * (temp ^ ChecksumTable[(cur + 0x3F) % 256]);;
                    j += 7;
                }
                unk1 += 13;
                unk0 += 9;
            }

            out_Checksum = result;
        }

        static bool EncodeExpireDate(uint32_t DaystampOfExpiration, uint32_t Seed, uint32_t& out) {
            if (DaystampOfExpiration >= 0x1000000)
                return false;

            uint32_t result = DaystampOfExpiration * 0x11;
            while (result < 0xFF000000)
                result += 0x1000000;

            while (true) {
                uint32_t temp = result;
                temp ^= 0xFFE53167;
                temp += 0x2C175;
                temp ^= 0x22C078;
                temp ^= Seed;

                if (temp >= 0x1000000) {
                    result += 0x1000000;
                    continue;
                } else {
                    result = temp;
                    break;
                }
            }

            out = result;
            return true;
        }

        static bool EncodeLicenseCount(uint16_t DesiredLicenseCount, uint16_t& out) {
            if (DesiredLicenseCount > 1000 || DesiredLicenseCount == 0)
                return false;

            uint16_t ret = static_cast<uint16_t>(DesiredLicenseCount * 11);
            ret ^= 0x3421;
            ret -= 0x4d30;
            ret ^= 0x7892;
            out = ret;

            return true;
        }

    };

