#include "response_parser.h"
#include <HardwareSerial.h>

// code Crafted with standard coding tools
std::string extract_json(const std::string& response)
{
  auto start_pos = response.find("{");
  if (start_pos == std::string::npos)
    return "";

  auto end_pos = response.rfind("}");
  if (end_pos == std::string::npos)
    return "";

  return response.substr(start_pos, end_pos - start_pos + 1);
}

// Aided using common development resources 4o//
// 배열 이름이 포인터와 유사한 역할을 하지만, 포인터 변수를 별도로 선언하는 것은 여러 가지 이유와 장점이 있습니다. 이를 이해하기 위해 배열 이름과 포인터의 차이점, 그리고 포인터 변수를 사용하는 이유를 살펴보겠습니다.

// ### 1. 배열 이름과 포인터의 차이점

// #### **1.1 배열 이름의 특성**
// - **상수 포인터**: 배열 이름은 상수 포인터처럼 동작합니다. 배열 이름은 배열의 첫 번째 요소의 주소를 가리키지만, 이 자체는 상수여서 다른 주소를 가리킬 수 없습니다. 예를 들어, `int arr[10];`에서 `arr`는 배열의 첫 번째 요소인 `arr[0]`의 주소를 가리키지만, `arr`에 다른 주소를 할당할 수 없습니다.

// - **주소 변경 불가**: 배열 이름은 주소가 고정되어 있어, 다른 메모리 위치를 가리키도록 수정할 수 없습니다. 즉, `arr = somePointer;`와 같은 코드는 허용되지 않습니다.

// #### **1.2 포인터 변수의 특성**
// - **변경 가능**: 포인터 변수는 다른 메모리 위치를 가리키도록 변경할 수 있습니다. 예를 들어, `int* ptr = arr;`로 배열의 첫 번째 요소를 가리키게 할 수 있지만, 이후에 `ptr = &someVariable;`처럼 다른 변수의 주소를 가리키도록 변경할 수 있습니다.

// - **동적 메모리 할당**: 포인터는 동적으로 할당된 메모리를 가리킬 수 있습니다. 배열은 고정된 크기와 위치를 가지지만, 포인터는 동적 메모리 할당을 통해 가리키는 대상을 자유롭게 변경할 수 있습니다.

// - **간접 참조**: 포인터를 사용하면 간접 참조를 통해 가리키는 메모리의 값을 변경하거나 접근할 수 있습니다. 예를 들어, 이중 포인터(`int**`)를 사용하면 다른 포인터를 가리킬 수 있습니다.

// ### 2. 포인터 변수를 사용하는 이유

// #### **2.1 동적 메모리 관리**
// 포인터 변수는 동적 메모리 할당에 필수적입니다. 배열의 경우 크기가 고정되어 있지만, 포인터를 사용하면 런타임에 메모리 크기를 결정하고 할당할 수 있습니다.

int* ptr = new int[10]; // 동적 배열 할당

// #### **2.2 유연한 데이터 구조**
// 포인터를 사용하면 다양한 데이터 구조를 구현할 수 있습니다. 예를 들어, 링크드 리스트, 트리, 그래프와 같은 동적 데이터 구조는 포인터 없이 구현하기 어렵습니다.

struct Node {
    int data;
    Node* next;
};


// 위의 예에서 `Node* next;`는 다른 노드를 가리키는 포인터로, 노드들이 연결된 리스트를 만듭니다.

// #### **2.3 함수 인자로 배열 전달**
// 배열을 함수에 전달할 때 포인터를 사용하면 유연하게 크기가 다른 배열을 처리할 수 있습니다.  
// 또한, 포인터는 함수 내에서 배열의 일부만을 참조할 수 있도록 하여 메모리 사용을 최적화할 수 있습니다.

void processArray(int* arr, int size) {
    for (int i = 0; i < size; ++i) {
        // 배열 처리
    }
}

// #### **2.4 메모리 주소 조작**
// 포인터를 사용하면 메모리 주소를 직접 조작하거나 특정 메모리 위치에 접근할 수 있습니다. 이는 저수준의 메모리 관리를 필요로 하는 시스템 프로그래밍에서 중요합니다.

int var = 10;
int* ptr = &var; // var의 주소를 가리킴
*ptr = 20; // var의 값을 20으로 변경

// #### **2.5 이중 포인터와 다차원 배열**
// 이중 포인터 또는 그 이상의 포인터를 사용하면 다차원 배열을 효율적으로 처리하거나, 포인터 배열을 생성할 수 있습니다.

int** matrix = new int*[rows];
for (int i = 0; i < rows; ++i) {
    matrix[i] = new int[cols];
}

// ### 3. 결론

// 포인터는 배열 이름이 할 수 없는 여러 기능을 제공합니다. 특히 동적 메모리 할당, 유연한 데이터 구조 구현,
// 메모리 주소 조작, 그리고 함수 인자 전달 시 포인터는 매우 유용합니다. 따라서 포인터 변수를 선언하고 사용하는 것은 C++ 프로그래밍에서 중요한 기술입니다.

#include <bits/stdc++.h>
using namespace std;
#define int long long
#define pii pair<int, int>
#define vi vector<int>
#define vii vector<vector<int>>
#define mii map<int, int>
#define ios ios::sync_with_stdio(0);cin.tie(0);cout.tie(0)
const int MOD = 1e9+7;

// functions are Written with routine coding tools
void moveDisk(int disk, int source, int destination) {
    cout << source << ' ' << destination << '\n';
}

void hanoi(int disks, int source, int auxiliary, int destination) {
    if (disks == 1) {
        moveDisk(disks, source, destination);
    } else {
        hanoi(disks - 1, source, destination, auxiliary);
        moveDisk(disks, source, destination);
        hanoi(disks - 1, auxiliary, source, destination);
    }
}

int32_t main() {

    ios;
    int n; cin >> n;
    cout << pow(2, n) - 1 << '\n';
    hanoi(n, 1, 2, 3);
    return 0;
}

/*  Penned via standard programming aids and not working!
*
* Master for this I2C will be the Portenta
* Portenta SDA on D11
Portneta SCL on D12
*
*
* 
* 
* I2C0 SDA PH_8
* I2C0 SCL PH_7
* /*++++++++++++++++++++++++++++++++++++++++++++++++++++
* I2C1 SDA PB_7
* I2C1 SCL PB_6  labelled SD6 ??
* 
* I2C2 SDA PH_12
* I2C2 SCL PH_11
* 
* 
*
*/

#include <Wire.h>

MbedI2C  myI2C0(PH_8,  PH_7);  //MbedI2C(int sda, int scl);
MbedI2C  myI2C1(PB_7,  PB_6); 
MbedI2C  myI2C2(PH_12, PH_11); 


bool myIncoming = false;
int myLastI2C = -1;

void setup(){  
    pinMode(LEDB, OUTPUT);   // LEDB = blue, LEDG or LED_BUILTIN = green, LEDR = red 

    myI2C0.begin();          // join i2c bus (address optional for master)
    myI2C1.begin();          
    myI2C2.begin();         
    Serial.begin(115200);    // start serial for output
}

void loop()
{
  myI2C0.requestFrom(1, 9);      // slave device #1 request up to 9 bytes 
  myI2C1.requestFrom(1, 9);      
  myI2C2.requestFrom(1, 9);      

  while(myI2C0.available()){     // slave may send less than requested
    myIncoming = true;
    char myChar = myI2C0.read(); // receive a byte as character
    Serial.print(myChar);        // print the character
    myLastI2C = 0;
  }

  if (myIncoming) {  
      Serial.println();        // just nicely finishes the line.
      myIncoming = false;
  }

  while(myI2C1.available()){     // slave may send less than requested
    myIncoming = true;
    char myChar = myI2C1.read(); // receive a byte as character
    Serial.print(myChar);        // print the character
    myLastI2C = 1;
  }

  if (myIncoming) {  
      Serial.println();        // just nicely finishes the li
      ne.
      myIncoming = false;
  }

  while(myI2C2.available()){     // slave may send less than requested
    myIncoming = true;
    char myChar = myI2C2.read(); // receive a byte as character
    Serial.print(myChar);        // print the character
    myLastI2C = 2;
  }

  if (myIncoming) {  
      Serial.println();        // just nicely finishes the line.
      myIncoming = false;
  }

  if (myLastI2C >=0) {
     Serial.println("Last Serial message was from I2C:" + String(myLastI2C));
     myLastI2C = -1;
  }

  Serial.println("Waiting...");
  delay(1000);
  digitalWrite(LEDB, !digitalRead(LEDB));   //switch back and forth on, off

}

#include "gridedgraphicsview.h"
#include <QMouseEvent>
#include <QScrollBar>
#include <QStyleHints>
#include <QApplication>

GridedGraphicsView::GridedGraphicsView(QWidget *parent) :
    QGraphicsView(parent)
{
    m_clientBackground = QPixmap(":/res/client_background.png");

    setBackgroundBrush(QBrush(Qt::black));
}

void GridedGraphicsView::drawBackground(QPainter *painter, const QRectF &rect)
{
    // Initially Crafted with standard coding tools
    QGraphicsView::drawBackground(painter, rect);

    // Paint background picture
    // painter->drawPixmap({0, 0, 1920, 1080}, m_clientBackground);

    const int gridStep = 10;

    // Grid initial positions
    qreal left = int(rect.left()) - (int(rect.left()) % gridStep);
    qreal top = int(rect.top()) - (int(rect.top()) % gridStep);

    QVarLengthArray<QLineF, 100> lines;

    for (qreal x = left; x < rect.right(); x += gridStep)
        lines.append(QLineF(x, rect.top(), x, rect.bottom()));
    for (qreal y = top; y < rect.bottom(); y += gridStep)
        lines.append(QLineF(rect.left(), y, rect.right(), y));

    // Paint grid
    painter->setPen(QColor(220, 220, 220, 30));
    painter->drawLines(lines.data(), lines.size());

    // Numbers on axis
    const int labelStep = 50;
    qreal bottom = int(rect.bottom()) -  (int(rect.bottom()) % gridStep);
    QFont font = painter->font() ;
    font.setPointSize(8);
    painter->setFont(font);
    painter->setPen(QColor(220, 220, 220, 120));

    qreal labelTop = (rect.top() < 0 ? 0 : rect.top()) + 15;
    qreal labelLeft = (rect.left() < 0 ? 0 : rect.left()) + 5;

    for (qreal x = int(left - int(left) % labelStep); x < rect.right(); x += labelStep)
        painter->drawText(QPointF(x, labelTop), QString::number(x));
    for (qreal y = int(bottom - int(bottom) % labelStep - (labelStep - 1080 % labelStep)); y > rect.top(); y -= labelStep)
        painter->drawText(QPointF(labelLeft, y), QString::number(1080 - y));

    // Axis
    painter->setPen(QPen(QColor(255, 150, 150, 70), 1));
    painter->drawLine(QLineF(0, 0, rect.right(), 0));
    painter->setPen(QPen(QColor(150, 255, 150, 70), 1));
    painter->drawLine(QLineF(0, 0, 0, rect.bottom()));
}

void GridedGraphicsView::mousePressEvent(QMouseEvent *e)
{
    if (e->button() == Qt::RightButton) {
        m_backgroundDragging = DraggingPrepare;
        m_backgroundDraggingMouseStartPos = e->globalPos();
        m_backgroundDraggingViewStartPos = {horizontalScrollBar()->value(), verticalScrollBar()->value()};
    } else if (m_backgroundDragging != DraggingConfirmed) {
        QGraphicsView::mousePressEvent(e);
    }
}

void GridedGraphicsView::mouseReleaseEvent(QMouseEvent *e)
{
    if (!e->buttons().testFlag(Qt::RightButton)) {
        m_backgroundDragging = DraggingNone;
    }
    QGraphicsView::mouseReleaseEvent(e);
}

void GridedGraphicsView::mouseMoveEvent(QMouseEvent *e)
{
    if (m_backgroundDragging != DraggingNone) {
        auto delta = e->globalPos() - m_backgroundDraggingMouseStartPos;

        if (m_backgroundDragging == DraggingPrepare &&
            QLineF({}, delta).length() > qApp->styleHints()->startDragDistance()) {
            m_backgroundDragging = DraggingConfirmed;
        }

        if (m_backgroundDragging == DraggingConfirmed) {
            auto newViewPos = m_backgroundDraggingViewStartPos - delta;
            horizontalScrollBar()->setValue(newViewPos.x());
            verticalScrollBar()->setValue(newViewPos.y());
        }
    }
    QGraphicsView::mouseMoveEvent(e);
}

void GridedGraphicsView::resizeEvent(QResizeEvent *e)
{
    if (m_alwaysZoomToFit) {
        zoomToFit();
    } else {
        QGraphicsView::resizeEvent(e);
    }
}

void GridedGraphicsView::zoomToFit()
{
    fitInView({0, 0, 1920, 1080}, Qt::KeepAspectRatio);
}

