// Note we don't ref count the nodes becasue it's ignored when the Actor is deleted, and calling Release after that can corrupt memory

const char *leftBreastName = "NPC L Breast";
const char *rightBreastName = "NPC R Breast";
const char *leftButtName = "NPC L Butt";
const char *rightButtName = "NPC R Butt";
const char *bellyName = "HDT Belly";

const char *scrotumName = "NPC GenitalsScrotum [GenScrot]";
const char *leftScrotumName = "NPC L GenitalsScrotum [LGenScrot]";
const char *rightScrotumName = "NPC R GenitalsScrotum [RGenScrot]";

std::unordered_map<const char *, std::string> configMap = {
	{leftBreastName, "Breast"}, {rightBreastName, "Breast"},
	{leftButtName, "Butt"}, {rightButtName, "Butt"},
	{bellyName, "Belly"} };


std::vector<const char *> femaleBones = { leftBreastName, rightBreastName, leftButtName, rightButtName, bellyName };

SimObj::SimObj(Actor *actor, config_t &config)
	: things(5){
	id = actor->formID;
}

SimObj::~SimObj() {
}


bool SimObj::bind(Actor *actor, std::vector<const char *>& boneNames, config_t &config)
{
	//logger.error("bind\n");


	auto loadedState = actor->loadedState;
	if (loadedState && loadedState->node) {
		bound = true;

		things.clear();
		for (const char * &b : boneNames) {
			BSFixedString cs(b);
			auto bone = loadedState->node->GetObjectByName(&cs.data);
			if (!bone) {
				logger.info("Failed to find Bone %s for actor %d\n", b, actor->formID);
			} else {
				things.emplace(b, Thing(bone, cs));
			}
		}
		updateConfig(config);
		return  true;
	}
	return false;
}

bool SimObj::actorValid(Actor *actor) {
	if (actor->flags & TESForm::kFlagIsDeleted)
		return false;
	if (actor && actor->loadedState && actor->loadedState->node)
		return true;
	return false;
}


void SimObj::update(Actor *actor) {
	if (!bound)
		return;
	//logger.error("update\n");
	for (auto &t : things) {
		t.second.update(actor);
	}
	//logger.error("end SimObj update\n");
}

bool SimObj::updateConfig(config_t & config) {
	for (auto &t : things) {
		std::string &section = configMap[t.first];
		auto &centry = config[section];
		t.second.updateConfig(centry);
	}
	return true;
}

#include <vector>

#include "cascade-classifier.h"
#include "integral-image.h"
#include "strong-classifier.h"

/**
 * Constructor
 * @param {Int} baseResolution Base resolution for the cascade classifer
 */
CascadeClassifier::CascadeClassifier(int baseResolution) {
	this->baseResolution = baseResolution;
}

/**
 * Constructor
 * @param {Int}                           baseResolution Base resolution for the cascade classifier
 * @param {std::vector<StrongClassifier>} sc             A set of strong classifiers to add as layers
 */
CascadeClassifier::CascadeClassifier(int baseResolution, std::vector<StrongClassifier> sc) {
	this->baseResolution = baseResolution;
	this->strongClassifiers = sc;
}

/**
 * Destructively scale a cascade classifier relative to its base resolution
 * @param {Float} factor The factor by which to scale
 */
void CascadeClassifier::scale(float factor) {
	this->baseResolution *= factor;
	for (int i = 0; i < this->strongClassifiers.size(); i += 1) this->strongClassifiers[i].scale(factor);
}

/**
 * Add a strong classifier as a layer to a cascade classifier
 * @param {StrongClassifier} sc The strong classifier to add
 */
void CascadeClassifier::add(StrongClassifier sc) {
	this->strongClassifiers.push_back(sc);
}

/**
 * Remove the most recently added strong classifier associated with a cascade classifier
 */
void CascadeClassifier::removeLast() {
	this->strongClassifiers.pop_back();
}

/**
 * Classify a region of an integral image
 * @param  {IntegralImage} integral The integral image to classify
 * @param  {Int}           sx       Subwindow x offset
 * @param  {Int}           sy       Subwindow y offset
 * @param  {Float}         mean     The mean of the values within the subwindow (for post-normalization)
 * @param  {Float}         sd       The standard deviation of the values within the subwindow (for post normalization)
 * @return {Bool}                   True for positive detection, false for negative
 */
bool CascadeClassifier::classify(IntegralImage& integral, int sx, int sy, float mean, float sd) {
	for (int i = 0; i < this->strongClassifiers.size(); i += 1) {
		if (this->strongClassifiers[i].classify(integral, sx, sy, mean, sd) == false) return false;
	}
	return true;
}

/**
 * Get false positive rate for a cascade classifier
 * @param  {std::vector<IntegralImage>} negativeValidationSet A set of negative images to test
 * @return {Float}                                            Normalized false positive rate
 */
float CascadeClassifier::getFPR(std::vector<IntegralImage>& negativeValidationSet) {
	int falsePositives = 0;
	for (int i = 0; i < negativeValidationSet.size(); i += 1) {
		if (this->classify(negativeValidationSet[i], 0, 0, 0, 1) == true) falsePositives += 1;
	}
	return (float)falsePositives / negativeValidationSet.size();
}

/**
 * Get false negative rate for a cascade classifier
 * @param  {std::vector<IntegralImage>} positiveValidationSet A set of positive images to test
 * @return {Float}                                            Normalized false negative rate
 */
float CascadeClassifier::getFNR(std::vector<IntegralImage>& positiveValidationSet) {
	int falseNegatives = 0;
	for (int i = 0; i < positiveValidationSet.size(); i += 1) {
		if (this->classify(positiveValidationSet[i], 0, 0, 0, 1) == false) falseNegatives += 1;
	}
	return (float)falseNegatives / positiveValidationSet.size();
}

#include "tictactoe.hpp"

// using namespace eosio should really be here rather than in the header

void tictactoe::create(const name &challenger, name &host) {
    require_auth(host);
    check(challenger != host, "Challenger should not be the same as the host.");

    // Check if game already exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr == existingHostGames.end(), "Game already exists.");

    existingHostGames.emplace(host, [&](auto &g) {
        g.challenger = challenger;
        g.host = host;
        g.turn = host;
    });
}

void tictactoe::restart(const name &challenger, const name &host, const name &by)
{
    check(has_auth(by), "Only " + by.to_string() + "can restart the game.");

    // Check if game exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr != existingHostGames.end(), "Game does not exist.");

    // Check if this game belongs to the action sender
    check(by == itr->host || by == itr->challenger, "This is not your game.");

    // Reset game
    existingHostGames.modify(itr, itr->host, [](auto &g) {
        g.resetGame();
    });
}

void tictactoe::close(const name &challenger, const name &host)
{
    check(has_auth(host), "Only the host can close the game.");

    require_auth(host);

    // Check if game exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr != existingHostGames.end(), "Game does not exist.");

    // Remove game
    existingHostGames.erase(itr);
}

bool tictactoe::isEmptyCell(const uint8_t &cell)
{
    return cell == 0;
}

bool tictactoe::isValidMove(const uint16_t &row, const uint16_t &column, const std::vector<uint8_t> &board)
{
    uint32_t movementLocation = row * game::boardWidth + column;
    bool isValid = movementLocation < board.size() && isEmptyCell(board[movementLocation]);
    return isValid;
}

name tictactoe::getWinner(const game &currentGame)
{
    auto &board = currentGame.board;

    bool isBoardFull = true;

    // Use bitwise AND operator to determine the consecutive values of each column, row and diagonal
    // Since 3 == 0b11, 2 == 0b10, 1 = 0b01, 0 = 0b00
    std::vector<uint32_t> consecutiveColumn(game::boardWidth, 3);
    std::vector<uint32_t> consecutiveRow(game::boardHeight, 3);
    uint32_t consecutiveDiagonalBackslash = 3;
    uint32_t consecutiveDiagonalSlash = 3;

    for (uint32_t i = 0; i < board.size(); i++)
    {
        isBoardFull &= isEmptyCell(board[i]);
        uint16_t row = uint16_t(i / game::boardWidth);
        uint16_t column = uint16_t(i % game::boardWidth);

        // Calculate consecutive row and column value
        consecutiveRow[column] = consecutiveRow[column] & board[i];
        consecutiveColumn[row] = consecutiveColumn[row] & board[i];
        // Calculate consecutive diagonal \ value
        if (row == column)
        {
            consecutiveDiagonalBackslash = consecutiveDiagonalBackslash & board[i];
        }
        // Calculate consecutive diagonal / value
        if (row + column == game::boardWidth - 1)
        {
            consecutiveDiagonalSlash = consecutiveDiagonalSlash & board[i];
        }
    }

    // Inspect the value of all consecutive row, column, and diagonal and determine winner
    std::vector<uint32_t> aggregate = {consecutiveDiagonalBackslash, consecutiveDiagonalSlash};
    aggregate.insert(aggregate.end(), consecutiveColumn.begin(), consecutiveColumn.end());
    aggregate.insert(aggregate.end(), consecutiveRow.begin(), consecutiveRow.end());

    for (auto value : aggregate)
    {
        if (value == 1)
        {
            return currentGame.host;
        }
        else if (value == 2)
        {
            return currentGame.challenger;
        }
    }
    // Draw if the board is full, otherwise the winner is not determined yet
    return isBoardFull ? draw : none;
}

void tictactoe::move(const name &challenger, const name &host, const name &by, const uint16_t &row, const uint16_t &column)
{
    check(has_auth(by), "The next move should be made by " + by.to_string());

    // Check if game exists
    games existingHostGames(get_self(), host.value);
    auto itr = existingHostGames.find(challenger.value);
    check(itr != existingHostGames.end(), "Game does not exist.");

    // Check if this game hasn't ended yet
    check(itr->winner == none, "The game has ended.");

    // Check if this game belongs to the action sender
    check(by == itr->host || by == itr->challenger, "This is not your game.");
    // Check if this is the  action sender's turn
    check(by == itr->turn, "it's not your turn yet!");

    // Check if user makes a valid movement
    check(isValidMove(row, column, itr->board), "Not a valid movement.");

    // Fill the cell, 1 for host, 2 for challenger
    //TODO could use constant for 1 and 2 as well
    const uint8_t cellValue = itr->turn == itr->host ? 1 : 2;
    const auto turn = itr->turn == itr->host ? itr->challenger : itr->host;
    existingHostGames.modify(itr, itr->host, [&](auto &g) {
        g.board[row * game::boardWidth + column] = cellValue;
        g.turn = turn;
        g.winner = getWinner(g);
    });
}

