#include "PiNG12RAW.h"

Debayer::DebayerContainer::DebayerContainer(const char *inputfilename, unsigned int width, unsigned int height) {
    this->width = width;
    this->height = height;

    red_Gr.resize(width * height / 4);
    grn1Gr.resize(width * height / 4);
    grn2Gr.resize(width * height / 4);
    blueGr.resize(width * height / 4);

    inputfile.open(inputfilename, std::ios::binary);
    if (!inputfile) {
        std::cerr << "Error: Cannot open input file, exiting now!" << std::endl;
        exit(1);
    }
    iBuf = new char[width * height * 3 / 2];
    inputfile.read(iBuf, width * height * 3 / 2);
    inputfile.close();

    tempstr = new char[MAXTEMPSTRLEN];
}

int Debayer::DebayerContainer::ComputeChannels() {
    int row, col;
    int iOff;
    int runCount = width * height * 3 / 2;

    for (unsigned int rPtr = 0; rPtr < runCount; rPtr += 3) {
        row = (rPtr * 2 / 3) / width;
        col = (rPtr * 2 / 3) - width * row;

        if (row % 2 == 0) {
            row = row / 2;
            col = col / 2;
            iOff = row * (width / 2) + col;
            red_Gr[iOff] = iBuf[rPtr];
            grn1Gr[iOff] = (((uint8_t) iBuf[rPtr + 1] & 0x0F) << 4 |
                            (uint8_t) iBuf[rPtr + 2] >> 4);
        } else {
            row = row / 2;
            col = col / 2;
            iOff = row * (width / 2) + col;
            grn2Gr[iOff] = iBuf[rPtr];
            blueGr[iOff] = (((uint8_t) iBuf[rPtr + 1] & 0x0F) << 4 |
                            (uint8_t) iBuf[rPtr + 2] >> 4);
        }
    }
}

int Debayer::DebayerContainer::WriteChannels(const char *fileprefix) {
    int w = width / 2;
    int h = height / 2;

    return lodepng::encode(augmented(fileprefix, RED), red_Gr, w, h, LCT_GREY) ||
           lodepng::encode(augmented(fileprefix, GR1), grn1Gr, w, h, LCT_GREY) ||
           lodepng::encode(augmented(fileprefix, GR2), grn2Gr, w, h, LCT_GREY) ||
           lodepng::encode(augmented(fileprefix, BLU), blueGr, w, h, LCT_GREY);
}

int Debayer::DebayerContainer::WriteColored(const char *filename, DebayeringAlgorithm alg) {
    std::vector<unsigned char> result;
    result.resize(3 * (width) * (height));
    int imOff, grOff;

    switch (alg) {
        case LINEAR:
            for (unsigned int i = 0; i < height; i++) {
                for (unsigned int j = 0; j < width; j++) {
                    imOff = 3 * (i * width + j);
                    grOff = (i / 2) * width / 2 + (j / 2);
                    result[imOff + 0] = red_Gr[grOff];
                    result[imOff + 1] = (grn1Gr[grOff] + grn2Gr[grOff]) / 2;
                    result[imOff + 2] = blueGr[grOff];
                }
            }
            break;
        default:
            break;
    }

    return lodepng::encode(filename, result, width, height, LCT_RGB);
}

char *Debayer::DebayerContainer::augmented(const char *prefix, Channel ch) {
    strcpy(tempstr, prefix);
    switch (ch) {
        case RED:
            strcat(tempstr, "red.png");
            break;
        case GR1:
            strcat(tempstr, "gr1.png");
            break;
        case GR2:
            strcat(tempstr, "gr2.png");
            break;
        case BLU:
            strcat(tempstr, "blu.png");
            break;
    }
    return tempstr;
}

Debayer::DebayerContainer::~DebayerContainer() {
    delete tempstr;
    delete iBuf;
}

#include <iostream>
#include <iomanip>
#include <random>
#include <ctime>

#include "root_finder/root_finder.hpp"
#include "JenkinsTraub/jt.h"

using namespace std;
using namespace Eigen;

// Use Mersenne Twister as PRNG
std::mt19937_64 gen;
std::uniform_real_distribution<double> uniformReal(0.0, 1.0);

void testRootFinder(int order)
{
    int numRounds = 300000;
    double tol = 1e-8;
    int dispPrecision = 12;

    // Randomly geenrate polynomial whose all real roots lie in an interval
    set<double> realRoots;
    VectorXd coeffs(1);
    coeffs << 1;
    double tempRoot;
    for (int i = 1; i <= order; i++)
    {
        VectorXd b(2);
        tempRoot = (uniformReal(gen) - 0.5) * 10000;
        b << 1, -tempRoot;
        coeffs = RootFinder::polyConv(coeffs, b);
        realRoots.insert(tempRoot);
    }

    // Show ground truth
    cout << "------------------ Benchmark Companion Matrix Method, Roots Isolation Method, and Jenkins-Traub Algorithm ------------------" << endl;

    cout << "Ground Truth: " << endl;
    for (auto it = realRoots.begin(); it != realRoots.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;

    // Running root finder for multiple rounds
    set<double> rts1, rts2, rts3;
    VectorXd coeffsReversed = coeffs.reverse();
    VectorXcd rts3Vec;
    clock_t ini = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by eigen values of companion matrix
        rts1 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol, false);
    }
    clock_t mid1 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by real roots isolation, i.e., in (-inf, inf)
        rts2 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol);
    }
    clock_t mid2 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by Jenkins-Traub algorithm
        jt::findRootsJenkinsTraub(coeffsReversed, &rts3Vec);
    }
    clock_t fin = clock();

    // Results
    cout << "Average Execution Time for Companion Matrix Method: " << endl
         << (mid1 - ini) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Real Roots Isolation Method: " << endl
         << (mid2 - mid1) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Jenkins-Traub Algorithm: " << endl
         << (fin - mid2) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Roots Found by Companion Matrix Method: " << endl;
    for (auto it = rts1.begin(); it != rts1.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Real Roots Isolation Method: " << endl;
    for (auto it = rts2.begin(); it != rts2.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Jenkins-Traub Algorithm: " << endl;
    for (int i = 0; i < rts3Vec.size(); i++)
    {
        if (rts3Vec(i).imag() < tol)
        {
            rts3.insert(rts3Vec(i).real());
        }
    }
    for (auto it = rts3.begin(); it != rts3.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
}

int main(int argc, char **argv)
{

    testRootFinder(8);

    return 0;
}

#include <SDL2/SDL.h>
#include <GL/gl.h>

/*
Display a static triangle. 
This code serves as the base case.
Code Supported by standard GitHub tools on 06/12/25. 
*/

int main() {
    // Initialize SDL with video
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        return 1;
    }

    // Create SDL window with OpenGL context
    SDL_Window* window = SDL_CreateWindow("Static Triangle",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 500, 500, SDL_WINDOW_OPENGL);
    if (!window) {
        SDL_Quit();
        return 1;
    }

    SDL_GLContext gl_context = SDL_GL_CreateContext(window);

    // Main loop
    bool running = true;
    SDL_Event event;
    while (running) {

        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) running = false;
        }

        // OpenGL rendering
        glClearColor(0, 0, 0, 1);
        glClear(GL_COLOR_BUFFER_BIT);

        glBegin(GL_TRIANGLES);
            // top vertex 
            glColor3f(1.0, 0.0, 0.0); // Red
            glVertex2f(0.0f, 0.5f);

            // left vertex
            glColor3f(0.0, 1.0, 0.0); // Green
            glVertex2f(-0.5f, -0.5f);

            // right vertex
            glColor3f(0.0, 0.0, 1.0); // Blue
            glVertex2f(0.5f, -0.5f);
        glEnd();

        SDL_GL_SwapWindow(window);
    }

    SDL_GL_DeleteContext(gl_context);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

// CCC '07 S4 - Waterpark (DMOJ): https://dmoj.ca/problem/ccc07s4
// ANNOTATED CODE - https://dmoj.ca/src/6786189
#include <bits/stdc++.h>
using namespace std;
const int MM = 1e4+3;
int N, dp[MM], a, b; vector<int> adj[MM]; // let dp[i] represent the number of ways to reach node i
// the best way to understand this solution is to draw it out and see why I am reversing the edges
/*
Instead of calculating the number of ways to go from node 1 to N
We can reverse the problem: number of ways to come backward to each node, starting from node N to 1
We want to find the number of ways to go from node N to 1
but we can only solve that if we solve the problem for node N-1 to 1
..... we start all the way from node 1, solving each subproblem to the base case: dp[1] = 1
let's say we didn't reverse the edges, then the only way to process the nodes in order is by doing topological sort to find the ordering and perform dp based on that ordering
you would also have to do dp[nxt] += dp[i] instead of dp[i] += dp[nxt] (if you want to see this more annoying solution go to the bottom of this code)
but in the loop we need to start from 2 and go forwards since we want to start from the smallest problem (except n = 1) and move up
*/
int main(){
    cin >> N >> a >> b;
    while(a != 0 && b != 0){ // the number of edges (M) is not given, only til we reach 0 0 is when the program stops taking input
        adj[b].push_back(a); // reverse the edge to go backwards and solve the sub problem
        cin >> a >> b; 
    } // dp[i] number of ways to reach node i from node 1
    dp[1] = 1; // base case: there is one way to reach node 1
    for(int i = 2; i <= N; i++){ // goes through the nodes in a forward fashion (PROBLEM GUARANTEES that for every edge, the smaller hill points to the bigger hill. that's why we can loop from 2 to N without using BFS or some algo)
        for(int nxt : adj[i]){ // for each neighbour of node i
            dp[i] += dp[nxt]; // since the neighbour leads to the current node, you are adding the number of ways from the neighbour node to the current node
        }
    }
    cout << dp[N] << endl; // final answer is the number of ways to reach node N
}

/*
funny way to also solve this problem (solving it without reversing edges) -> topo sort to figure out ordering + dp
the following is Assisted with basic coding tools that works when submitted
#include <bits/stdc++.h>
using namespace std;
const int MM = 1e4+3;
int N, dp[MM], inDeg[MM];
vector<int> adj[MM];
queue<int> q;
int main() {
    cin >> N;
    int u, v;
    while (cin >> u >> v && u && v) {
        adj[u].push_back(v); // Forward edges (no reversing)
        inDeg[v]++;         // Track dependencies
    }
    dp[1] = 1;  // Base case: Start at node 1
    // Step 1: Topological Sort
    for (int i = 1; i <= N; i++) 
        if (inDeg[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        // Step 2: Process neighbors
        for (int v : adj[u]) {
            dp[v] += dp[u];  // Count paths from u → v
            if (--inDeg[v] == 0) q.push(v); // Add to queue when all dependencies are done
        }
    }
    cout << dp[N] << endl; // Final result: ways to reach N
}
*/

/*
Link: https://leetcode.com/problems/3sum/
Approach: Two Pointers

The basic thinking logic for this is: Fix any one number in sorted array and find the other two numbers after it. The other two numbers can be easily found using two pointers (as array is sorted) and two numbers should have sum = -1*(fixed number).

Traverse the array and fix a number at every iteration.
If number fixed is +ve, break there because we can't make it zero by searching after it.
If number is getting repeated, ignore the lower loop and continue. This is for unique triplets. We want the last instance of the fixed number, if it is repeated.
Make two pointers start and end, and initialize sum as 0.
Search between two pointers, just similiar to binary search. Sum = num[i] + num[low] + num[high].
If sum is -ve, means, we need more +ve numbers to make it 0, increament start (start++).
If sum is +ve, means, we need more -ve numbers to make it 0, decreament end (end--).
If sum is 0, that means we have found the required triplet, push it in answer vector.
Now again, to avoid duplicate triplets, we have to navigate to last occurences of num[start] and num[end] respectively. 

*/


#include<bits/stdc++.h>
using namespace std;

vector<vector<int>> threeSum(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> v;
        sort(nums.begin(),nums.end());    // sorting the array acc. to logic
        int start,end,sum =0;
        for(int i=0;i<n;i++){
            if(nums[i]>0) break;      // If number fixed is +ve, stop there because we can't make it zero by searching after it.
            if(i>0 && nums[i] == nums[i-1]) continue;     // If number is getting repeated, ignore the lower loop and continue.
            start = i+1;
            end = n-1;
            while(start<end) {
                sum = nums[i] + nums[start] + nums[end];
                if(sum > 0) end--;   
                else if(sum <0) start++;
                else {
                    v.push_back({nums[i], nums[start], nums[end]});
                    start++;
                    end--;
                    while(start < end && nums[start] == nums[start-1])
                        start++;
                    while(start < end && nums[end] == nums[end+1])
                        end--;
                }
            }
        }
    return v;
}

int main() {

    int n;
    cin>>n;
    vector<int> arr(n);
    vector<vector<int>> ans;
    for(int i=0; i<n; i++) {
        cin>>arr[i];
    }
    ans = threeSum(arr);

    cout<<"Output: \n";
    for(int i=0; i<ans.size(); i++){
        for(int j=0;j<ans[i].size();j++) {
            cout<<ans[i][j]<< " ";
        }
        cout<<endl;
    }

    return 0;
}

