	shared_ptr<char> spcName(new char[wcNameSize], std::default_delete<char[]>());
	{
		size_t c_size;
		wcstombs_s(&c_size, spcName.get(), wcNameSize, wcName, wcNameSize);
	}
	//delete wcName;
