struct position {
    int x;
    int y;
    int health = 30;
};

const int ROW_SIZE = 10;
const int COL_SIZE = 20;
int enemyX = COL_SIZE / 5;
int enemyY = ROW_SIZE / 5;

void drawLine(int size) {
    for (int elemNumber = 0; elemNumber < size; elemNumber++)
        cout << "=";
    cout << endl;
}

void drawMap(char map[ROW_SIZE][COL_SIZE], position player) {
    for (int row = 0; row < ROW_SIZE; row++) {
        for (int col = 0; col < COL_SIZE; col++) {
            if (row == player.y && col == player.x)
                cout << "@";
            else
                cout << map[row][col];
        }
        cout << endl;
    }
}

void mapInit(char map[ROW_SIZE][COL_SIZE], char playerMap[ROW_SIZE][COL_SIZE]) {
    for (int row = 0; row < ROW_SIZE; row++) {
        for (int col = 0; col < COL_SIZE; col++) {
            if (row == 0 || col == 0 || row == ROW_SIZE - 1 || col == COL_SIZE - 1)
                map[row][col] = '*';
            else {
                int chance = rand() % 10;
                switch(chance) {
                case 1: map[row][col] = 's'; break;
                case 2: map[row][col] = 't'; break;
                default: map[row][col] = ' ';
                }
            }
            playerMap[row][col] = '*';
        }
    }
}

bool checkPosition(char map[ROW_SIZE][COL_SIZE], position pos) {
    char item = map[pos.y][pos.x];
    return item == ' ';
}

bool checkPositionEnemy(char map[ROW_SIZE][COL_SIZE], int enemyX, int enemyY) {
    char item = map[enemyX][enemyY];
    return item == ' ';
}

bool updatePlayerPosition(char map[ROW_SIZE][COL_SIZE], char direction, position *player) {
    position tempPosition;
    tempPosition = *player;
    switch (direction) {
    case 'w': tempPosition.y--; break;
    case 's': tempPosition.y++; break;
    case 'a': tempPosition.x--; break;
    case 'd': tempPosition.x++; break;
    }
    if (checkPosition(map, tempPosition)) {
        *player = tempPosition;
        return true;
    }
    return false;
}

void updatePlayerMap(char map[ROW_SIZE][COL_SIZE], char playerMap[ROW_SIZE][COL_SIZE], position player) {
    for (int row = player.y-2; row <= player.y+2; row++) {
        for (int col = player.x - 2; col <= player.x + 2; col++) {
            playerMap[row][col] = map[row][col];
            if (row == enemyY && col == enemyX)
                playerMap[row][col] = 'e';
        }
    }
}

//
//Supported via standard programming aids
// Function to update enemy position towards player
void updateEnemyPosition(char map[ROW_SIZE][COL_SIZE], int playerX, int playerY) {
    if (enemyX < playerX) {
        enemyX++;
    } else if (enemyX > playerX) {
        enemyX--;
    }

    if (enemyY < playerY) {
        enemyY++;
    } else if (enemyY > playerY) {
        enemyY--;
    }
}

int main()
{
    srand(time(NULL));

    char map[ROW_SIZE][COL_SIZE];
    char playerMap[ROW_SIZE][COL_SIZE];

    position player;
    player.x = COL_SIZE / 2;
    player.y = ROW_SIZE / 2;
    char direction = ' ';

    mapInit(map, playerMap);

    while (player.health > 0) {
        cout << "Player health: " << player.health << endl;
        drawMap(playerMap, player);
        drawLine(COL_SIZE);

        cout << "Enter direction: ";
        cin >> direction;
        if (updatePlayerPosition(map, direction, &player))
            updatePlayerMap(map, playerMap, player);
            updateEnemyPosition(map, player.x, player.y);
            if (abs(enemyX - player.x) <= 1 && abs(enemyY - player.y) <= 1) {
                player.health -= 3;
            }
        //system("CLS");
    }

    return 0;
}

#include "buffer/buffer_pool_manager.h"

namespace cmudb {

/*
 * BufferPoolManager Constructor
 * When log_manager is nullptr, logging is disabled (for test purpose)
 * WARNING: Do Not Edit This Function
 */
BufferPoolManager::BufferPoolManager(size_t pool_size,
                                                 DiskManager *disk_manager,
                                                 LogManager *log_manager)
    : pool_size_(pool_size), disk_manager_(disk_manager),
      log_manager_(log_manager) {
  // a consecutive memory space for buffer pool
  pages_ = new Page[pool_size_];
  page_table_ = new ExtendibleHash<page_id_t, Page *>(BUCKET_SIZE);
  replacer_ = new LRUReplacer<Page *>;
  free_list_ = new std::list<Page *>;

  // put all the pages into free list
  for (size_t i = 0; i < pool_size_; ++i) {
    free_list_->push_back(&pages_[i]);
  }
}

/*
 * BufferPoolManager Deconstructor
 * WARNING: Do Not Edit This Function
 */
BufferPoolManager::~BufferPoolManager() {
  delete[] pages_;
  delete page_table_;
  delete replacer_;
  delete free_list_;
}

/**
 * 1. search hash table.
 *  1.1 if exist, pin the page and return immediately
 *  1.2 if no exist, find a replacement entry from either free list or lru
 *      replacer. (NOTE: always find from free list first)
 * 2. If the entry chosen for replacement is dirty, write it back to disk.
 * 3. Delete the entry for the old page from the hash table and insert an
 * entry for the new page.
 * 4. Update page metadata, read page content from disk file and return page
 * pointer
 *
 * This function must mark the Page as pinned and remove its entry from LRUReplacer before it is returned to the caller.
 */
Page *BufferPoolManager::FetchPage(page_id_t page_id) {
  lock_guard<mutex> lck(latch_);
  Page *tar = nullptr;
  if (page_table_->Find(page_id,tar)) { //1.1
    tar->pin_count_++;
    replacer_->Erase(tar);
    return tar;
  }
  //1.2
  tar = GetVictimPage();
  if (tar == nullptr) return tar;
  //2
  if (tar->is_dirty_) {
    disk_manager_->WritePage(tar->GetPageId(),tar->data_);
  }
  //3
  page_table_->Remove(tar->GetPageId());
  page_table_->Insert(page_id,tar);
  //4
  disk_manager_->ReadPage(page_id,tar->data_);
  tar->pin_count_ = 1;
  tar->is_dirty_ = false;
  tar->page_id_= page_id;

  return tar;
}
//Page *BufferPoolManager::find

/*
 * Implementation of unpin page
 * if pin_count>0, decrement it and if it becomes zero, put it back to
 * replacer if pin_count<=0 before this call, return false. is_dirty: set the
 * dirty flag of this page
 */
bool BufferPoolManager::UnpinPage(page_id_t page_id, bool is_dirty) {
  lock_guard<mutex> lck(latch_);
  Page *tar = nullptr;
  page_table_->Find(page_id,tar);
  if (tar == nullptr) {
    return false;
  }
  tar->is_dirty_ = is_dirty;
  if (tar->GetPinCount() <= 0) {
    return false;
  }
  ;
  if (--tar->pin_count_ == 0) {
    replacer_->Insert(tar);
  }
  return true;
}

/*
 * Used to flush a particular page of the buffer pool to disk. Should call the
 * write_page method of the disk manager
 * if page is not found in page table, return false
 * NOTE: make sure page_id != INVALID_PAGE_ID
 */
bool BufferPoolManager::FlushPage(page_id_t page_id) {
  lock_guard<mutex> lck(latch_);
  Page *tar = nullptr;
  page_table_->Find(page_id,tar);
  if (tar == nullptr || tar->page_id_ == INVALID_PAGE_ID) {
    return false;
  }
  if (tar->is_dirty_) {
    disk_manager_->WritePage(page_id,tar->GetData());
    tar->is_dirty_ = false;
  }

  return true;
}

/**
 * User should call this method for deleting a page. This routine will call
 * disk manager to deallocate the page. First, if page is found within page
 * table, buffer pool manager should be reponsible for removing this entry out
 * of page table, reseting page metadata and adding back to free list. Second,
 * call disk manager's DeallocatePage() method to delete from disk file. If
 * the page is found within page table, but pin_count != 0, return false
 */
bool BufferPoolManager::DeletePage(page_id_t page_id) {
  lock_guard<mutex> lck(latch_);
  Page *tar = nullptr;
  page_table_->Find(page_id,tar);
  if (tar != nullptr) {
    if (tar->GetPinCount() > 0) {
      return false;
    }
    replacer_->Erase(tar);
    page_table_->Remove(page_id);
    tar->is_dirty_= false;
    tar->ResetMemory();
    free_list_->push_back(tar);
  }
  disk_manager_->DeallocatePage(page_id);
  return true;
}

/**
 * User should call this method if needs to create a new page. This routine
 * will call disk manager to allocate a page.
 * Buffer pool manager should be responsible to choose a victim page either
 * from free list or lru replacer(NOTE: always choose from free list first),
 * update new page's metadata, zero out memory and add corresponding entry
 * into page table. return nullptr if all the pages in pool are pinned
 */
Page *BufferPoolManager::NewPage(page_id_t &page_id) {
  lock_guard<mutex> lck(latch_);
  Page *tar = nullptr;
  tar = GetVictimPage();
  if (tar == nullptr) return tar;

  page_id = disk_manager_->AllocatePage();
  //2
  if (tar->is_dirty_) {
    disk_manager_->WritePage(tar->GetPageId(),tar->data_);
  }
  //3
  page_table_->Remove(tar->GetPageId());
  page_table_->Insert(page_id,tar);

  //4
  tar->page_id_ = page_id;
  tar->ResetMemory();
  tar->is_dirty_ = false;
  tar->pin_count_ = 1;

  return tar;
}

Page *BufferPoolManager::GetVictimPage() {
  Page *tar = nullptr;
  if (free_list_->empty()) {
    if (replacer_->Size() == 0) {
      return nullptr;
    }
    replacer_->Victim(tar);
  } else {
    tar = free_list_->front();
    free_list_->pop_front();
    assert(tar->GetPageId() == INVALID_PAGE_ID);
  }
  assert(tar->GetPinCount() == 0);
  return tar;
}

} // namespace cmudb

/**
 * @file buffer_pool_manager.cpp
 * @author sheep
 * @brief implementation of buffer pool manager
 * @version 0.1
 * @date 2022-04-30
 * 
 * @copyright Copyright (c) 2022
 * 
 */

#ifndef BUFFER_POOL_MANAGER_CPP
#define BUFFER_POOL_MANAGER_CPP

#include "buffer/buffer_pool_manager.h"
#include "buffer/lru_replacer.h"
#include "common/logger.h"
#include "recovery/log_manager.h"
#include "storage/page/page_header.h"

namespace TinyDB {

BufferPoolManager::BufferPoolManager(size_t pool_size, DiskManager *disk_manager, LogManager *log_manager)
    : pool_size_(pool_size), disk_manager_(disk_manager), log_manager_(log_manager) {
    // allocate the in-memory page array
    pages_ = new Page[pool_size_];
    // pool size has no meaning for lru replacer, because we(buffer pool manager)
    // are controlling the page num
    replacer_ = new LRUReplacer(pool_size_);

    // initially, every page is in the free list
    for (size_t i = 0; i < pool_size_; i++) {
        free_list_.emplace_back(static_cast<frame_id_t>(i));
    }
}

BufferPoolManager::~BufferPoolManager() {
    delete[] pages_;
    delete replacer_;
}

Page *BufferPoolManager::FetchPage(page_id_t page_id, bool outbound_is_error) {
    std::lock_guard<std::mutex> guard(latch_);

    // if the page is cached
    auto it = page_table_.find(page_id);
    if (it != page_table_.end()) {
        auto page = &pages_[it->second];
        // pin this frame
        replacer_->Pin(it->second);
        // increment the pin count
        page->pin_count_ += 1;
        return page;
    }

    // allocate a new slot
    frame_id_t frame_id = -1;
    if (!free_list_.empty()) {
        // we will use free slot first
        frame_id = free_list_.back();
        free_list_.pop_back();
    } else {
        // otherwise, let's evict a page and reuse it's slot
        if (!replacer_->Evict(&frame_id)) {
            // maybe we should throw runtime error?
            // because this means there is no more slot.
            // or sleep on conditional variable waiting for a slot
            return nullptr;
        }

        auto page = &pages_[frame_id];
        if (page->is_dirty_) {
            FlushPageHelper(frame_id);
        }
        // evict this page
        page_table_.erase(page->GetPageId());
    }

    page_table_[page_id] = frame_id;

    auto page = &pages_[frame_id];
    // initialize the in-memory page representation
    page->page_id_ = page_id;
    page->is_dirty_ = false;
    page->pin_count_ = 1;
    disk_manager_->ReadPage(page_id, page->data_, outbound_is_error);

    return page;
}

bool BufferPoolManager::UnpinPage(page_id_t page_id, bool is_dirty) {
    std::lock_guard<std::mutex> guard(latch_);
    // failed to find this page
    auto it = page_table_.find(page_id);
    if (it == page_table_.end()) {
        return false;
    }
    frame_id_t frame_id = it->second;

    // update is_dirty flag
    pages_[frame_id].is_dirty_ = pages_[frame_id].is_dirty_ || is_dirty;

    // failed to unpin this page
    if (pages_[frame_id].pin_count_ == 0) {
        return false;
    }

    pages_[frame_id].pin_count_ -= 1;
    if (pages_[frame_id].pin_count_ == 0) {
        // put it into replacer
        replacer_->Unpin(frame_id);
    }

    return true;
}

bool BufferPoolManager::FlushPage(page_id_t page_id) {
    std::lock_guard<std::mutex> guard(latch_);
    // this page is not cached
    auto it = page_table_.find(page_id);
    if (it == page_table_.end()) {
        return false;
    }

    // flush to disk
    frame_id_t frame_id = it->second;
    FlushPageHelper(frame_id);

    return true;
}

void BufferPoolManager::FlushPageHelper(frame_id_t frame_id) {
    // write ahead log protocol: 
    // before writting a page into disk, all related logs has to be flush into disk first.
    auto page = &pages_[frame_id];
    if (log_manager_ != nullptr) {
        // get lsn of current page
        auto header = reinterpret_cast<PageHeader *>(page->GetData());
        auto lsn = header->GetLSN();
        // flush the log and record the time
        auto t1 = std::chrono::steady_clock::now();
        // force the log
        log_manager_->Flush(lsn, true);
        auto t2 = std::chrono::steady_clock::now();
        flush_wait_time_ += std::chrono::duration_cast<std::chrono::milliseconds>(t2 - t1);
    }
    disk_manager_->WritePage(page->GetPageId(), page->GetData());
    page->is_dirty_ = false;
}

Page *BufferPoolManager::NewPage(page_id_t *page_id) {
    std::lock_guard<std::mutex> guard(latch_);

    // no more space
    if (free_list_.empty() && replacer_->Size() == 0) {
        return nullptr;
    }

    // allocate new page from disk
    *page_id = disk_manager_->AllocatePage();

    frame_id_t frame_id = -1;
    if (!free_list_.empty()) {
        frame_id = free_list_.back();
        free_list_.pop_back();
    } else {
        if (!replacer_->Evict(&frame_id)) {
            return nullptr;
        }

        auto page = &pages_[frame_id];
        if (page->is_dirty_) {
            FlushPageHelper(frame_id);
        }

        page_table_.erase(page->GetPageId());
    }
    page_table_[*page_id] = frame_id;

    auto page = &pages_[frame_id];
    // initialize the in-memory page representation
    page->page_id_ = *page_id;
    page->is_dirty_ = false;
    page->pin_count_ = 1;
    page->ZeroData();

    return page;
}

bool BufferPoolManager::DeletePage(page_id_t page_id) {
    std::lock_guard<std::mutex> guard(latch_);
    // deallocate this page, return it to disk manager
    disk_manager_->DeallocatePage(page_id);
    auto it = page_table_.find(page_id);
    if (it == page_table_.end()) {
        // already removed
        return true;
    }

    frame_id_t frame_id = page_table_[page_id];
    // check whether other one is still using
    if (pages_[frame_id].pin_count_ > 0) {
        return false;
    }
    // reset page id, because this might interfere "FlushAllPages"
    pages_[frame_id].page_id_ = -1;

    page_table_.erase(page_id);
    // put this slot to free list
    free_list_.push_front(frame_id);
    // remove it from replacer
    replacer_->Pin(frame_id);
    return true;
}

void BufferPoolManager::FlushAllPages() {
    std::lock_guard<std::mutex> guard(latch_);

    // maybe we should iterate hash table?
    for (size_t i = 0; i < pool_size_; i++) {
        if (page_table_.count(pages_[i].GetPageId()) == 0) {
            continue;
        }
        FlushPageHelper(i);
    }
}

bool BufferPoolManager::CheckPinCount() {
    std::lock_guard<std::mutex> guard(latch_);
    bool flag = true;
    for (size_t i = 0; i < pool_size_; i++) {
        if (page_table_.count(pages_[i].GetPageId()) == 0) {
            continue;
        }
        if (pages_[i].GetPinCount() != 0) {
            LOG_ERROR("page %d has pin count %d", pages_[i].GetPageId(), pages_[i].GetPinCount());
            flag = false;
        }
    }
    return flag;
}

}

